import{_ as c,C as l,o,c as p,a5 as r,b as a,w as t,a as i,E as n,a6 as s}from"./chunks/framework.HSMtqGwj.js";const C=JSON.parse('{"title":"Handling Attribute Groups Directly","description":"","frontmatter":{},"headers":[],"relativePath":"implementation/direct-load.md","filePath":"implementation/direct-load.md","lastUpdated":1794851512000}'),h={name:"implementation/direct-load.md"};function u(f,e,m,b,g,y){const d=l("Mermaid");return o(),p("div",null,[e[2]||(e[2]=r('<h1 id="handling-attribute-groups-directly" tabindex="-1">Handling Attribute Groups Directly <a class="header-anchor" href="#handling-attribute-groups-directly" aria-label="Permalink to &quot;Handling Attribute Groups Directly&quot;">​</a></h1><p>TORCH distinguishes between directly loaded and referenced attributeGroups, where referenced attributeGroups are identified by the flag <code>IncludeReferenceOnly</code>. Directly loaded attributeGroups can be loaded directly as their inclusion in the extraction does not depend on any referencing.</p><p>TORCH loads all resources of the directly loaded attributeGroups based on the Fhir Profile specified in the attribute group and the filters applied to the attribute group. I.e. resources are loaded based on the Fhir Profile specified in the attribute group and the <a href="./../crtdl/filter.html">filters</a> applied to the attribute group.</p><p>The processing has two separate workflows due to the different nature of the resources:</p><ol><li><strong>Core Resources</strong>: These are resources that are outside the patient compartment (no direct link to Patient - e.g. Medication).</li><li><strong>Patient Resources</strong>: These are resources that are directly loaded and processed for each patient.</li></ol><h2 id="_1-directly-loaded-core-attribute-groups" tabindex="-1">1. Directly Loaded Core Attribute Groups <a class="header-anchor" href="#_1-directly-loaded-core-attribute-groups" aria-label="Permalink to &quot;1. Directly Loaded Core Attribute Groups&quot;">​</a></h2><p>Core attributes are simply loaded and processed in a single step.</p><p>This means that all resources that are part of the core attribute group are loaded and processed in a single fhir search request.</p><ul><li>After that a profile and must-have check is done on the resources. <ul><li>Must-have conditions are violated if <strong>not a single</strong> resource passes this check.</li></ul></li><li>If any <strong>must-have</strong> condition is violated, the extraction is fully stopped for the job.</li><li>At the same time it is sufficient if the must-have conditions are fulfilled for a single &quot;global&quot; resource.</li></ul>',9)),(o(),a(s,null,{default:t(()=>[n(d,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%09Start%5BStart%20Core%20Attribute%20Processing%5D%20--%3E%20Load%5B%22Load%20all%20core%20resources%3Cbr%2F%3Ein%20single%20FHIR%20search%20request%22%5D%0A%09Load%20--%3E%20Profile%5BProfile%20check%20on%20resources%5D%0A%09Profile%20--%3E%20MustHave%5BMust-have%20check%20on%20resources%5D%0A%09MustHave%20--%3E%20Check%7BAny%20must-have%20condition%20violated%3F%7D%0A%09Check%20--%3E%7Cyes%7C%20Stop%5BStop%20extraction%20for%20job%5D%0A%20%20%20%20Check%20--%3E%7Cno%7C%20Global%5B%22At%20least%20one%20resource%3Cbr%2F%3Efulfills%20must-have%20condition%22%5D%0A%09Global%20--%3E%20Complete%5BCore%20processing%20complete%5D%0A%09class%20Stop%20errorNode%0A%09class%20Complete%20successNode%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<h2 id="_2-directly-loaded-patient-attribute-groups" tabindex="-1">2. Directly Loaded Patient Attribute Groups <a class="header-anchor" href="#_2-directly-loaded-patient-attribute-groups" aria-label="Permalink to &quot;2. Directly Loaded Patient Attribute Groups&quot;">​</a></h2><p>Patient attribute groups are loaded and processed for each patient.</p><p>All resources from a patient attribute group are loaded and processed in a single fhir search request and then assigned to their patient.</p><ul><li><p>Each loaded resource is filtered against the patient&#39;s consent window; only resources within the consent period are processed further.</p><ul><li>When no consent codes are present in the cohort definition, all resources are considered consented by default.</li></ul></li><li><p>A profile and must-have check is done on every resource.</p></li><li><p>If after the group processing a must-have condition is violated, the respective patient is marked for deletion. Once all patients are processed, all resources (including the patient resource itself) for a patient marked for deletion are deleted. If no resources are left the whole batch is deleted.</p></li></ul>',4)),(o(),a(s,null,{default:t(()=>[n(d,{id:"mermaid-91",class:"mermaid",graph:"flowchart%20TD%0A%09Start%5BStart%20Patient%20Attribute%20Processing%5D%20--%3E%20ForEach%5BFor%20each%20group%5D%0A%09ForEach%20--%3E%20Load%5B%22Load%20patient%20resources%3Cbr%2F%3Ein%20single%20FHIR%20search%20request%22%5D%0A%09Load%20--%3E%20Assign%5BAssign%20resources%20to%20patient%5D%0A%09Assign%20--%3E%20Consent%5B%22Filter%20resources%20against%3Cbr%2F%3Epatient%20consent%20window%22%5D%0A%09Consent%20--%3E%20ConsentCodes%7BConsent%20codes%20in%20cohort%20definition%3F%7D%0A%09ConsentCodes%20--%3E%7Cno%7C%20AllConsent%5B%22All%20resources%20considered%3Cbr%2F%3Econsented%20by%20default%22%5D%0A%09ConsentCodes%20--%3E%7Cyes%7C%20OnlyConsent%5B%22Only%20resources%20within%3Cbr%2F%3Econsent%20window%20are%20processed%22%5D%0A%09AllConsent%20--%3E%20ProfileCheck%5B%22Profile%20and%20must-have%3Cbr%2F%3Echeck%20on%20every%20resource%22%5D%0A%09OnlyConsent%20--%3E%20ProfileCheck%0A%20%20%20%20ProfileCheck%20--%3E%20MustHaveViolated%7B%22Group%20processing%20violated%3Cbr%2F%3Emust-have%20condition%3F%22%7D%0A%09MustHaveViolated%20--%3E%7Cyes%7C%20MarkDelete%5BMark%20patient%20for%20deletion%5D%0A%09MustHaveViolated%20--%3E%7Cno%7C%20PatientComplete%5BPatient%20processing%20complete%5D%0A%09MarkDelete%20--%3E%20MorePatients%7BMore%20patients%20to%20process%3F%7D%0A%09PatientComplete%20--%3E%20MorePatients%0A%09MorePatients%20--%3E%7Cyes%7C%20ForEach%0A%09MorePatients%20--%3E%7Cno%7C%20DeleteMarked%5B%22Delete%20marked%20patient%3Cbr%2F%3Eresources%20from%20batch%22%5D%0A%09DeleteMarked%20--%3E%20AnyLeft%7BAny%20patients%20left%20in%20batch%3F%7D%0A%09AnyLeft%20--%3E%7Cno%7C%20DeleteBatch%5BDelete%20entire%20batch%5D%0A%09AnyLeft%20--%3E%7Cyes%7C%20BatchComplete%5BBatch%20processing%20complete%5D%0A%09class%20MarkDelete%20warnNode%0A%09class%20DeleteBatch%20errorNode%0A%09class%20BatchComplete%20successNode%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<h2 id="_3-assigning-resources-to-patients" tabindex="-1">3. Assigning Resources to Patients <a class="header-anchor" href="#_3-assigning-resources-to-patients" aria-label="Permalink to &quot;3. Assigning Resources to Patients&quot;">​</a></h2><p>For each resource type of the Patient compartment, TORCH uses <strong>one</strong> search parameter, taken from the <a href="https://hl7.org/fhir/R4/compartmentdefinition-patient.html" target="_blank" rel="noreferrer">Patient CompartmentDefinition</a> and the R4 SearchParameter definitions. The same parameter is used for three things:</p><ul><li>searching the resources of a batch&#39;s patients,</li><li>deciding which patient a loaded resource belongs to (this patient&#39;s consent is checked),</li><li>the standard attributes that are always extracted.</li></ul><p>The standard attribute is linked to the patient group. If the CRTDL declares the same element with <code>linkedGroups</code>, these groups are linked too. Then references to other resource types in that element, e.g. a <code>Practitioner</code> in <code>Appointment.participant.actor</code>, are resolved as well. Otherwise they are replaced by a data-absent-reason.</p><p>This matters most for types whose patient element routinely references other resource types:</p><table tabindex="0"><thead><tr><th>Resource type</th><th>Element that decides the patient</th></tr></thead><tbody><tr><td>Appointment</td><td><code>participant.actor</code></td></tr><tr><td>AppointmentResponse</td><td><code>actor</code></td></tr><tr><td>AuditEvent</td><td><code>agent.who</code>, <code>entity.what</code></td></tr><tr><td>Group</td><td><code>member.entity</code></td></tr><tr><td>Person</td><td><code>link.target</code></td></tr><tr><td>Provenance</td><td><code>target</code></td></tr><tr><td>Schedule</td><td><code>actor</code></td></tr><tr><td>SupplyRequest</td><td><code>deliverTo</code></td></tr></tbody></table><p>Only the <code>Patient</code> references in these elements decide the patient; references to other types are ignored for that.</p><p>The parameter is <code>_id</code> for <code>Patient</code>. For other types it is <code>patient</code> where the type defines it, otherwise the first parameter of the compartment definition that can reference a <code>Patient</code>. Only these types don&#39;t use <code>patient</code>:</p><table tabindex="0"><thead><tr><th>Resource type</th><th>Search parameter</th><th>Element that decides the patient</th></tr></thead><tbody><tr><td>AdverseEvent</td><td><code>subject</code></td><td><code>AdverseEvent.subject</code></td></tr><tr><td>Group</td><td><code>member</code></td><td><code>Group.member.entity</code></td></tr><tr><td>Schedule</td><td><code>actor</code></td><td><code>Schedule.actor</code></td></tr><tr><td>SupplyRequest</td><td><code>subject</code></td><td><code>SupplyRequest.deliverTo</code></td></tr></tbody></table><p>Only relative references of the form <code>Patient/&lt;id&gt;</code> count, optionally versioned (<code>Patient/&lt;id&gt;/_history/&lt;v&gt;</code>).</p><p>A loaded resource is handled as follows:</p><ul><li><strong>One patient:</strong> the resource is assigned to that patient.</li><li><strong>No patient:</strong> the resource is excluded as <code>PATIENT_NOT_FOUND</code>.</li><li><strong>Several distinct patients:</strong> the resource is not assigned to any of them and is excluded as <code>MULTIPLE_PATIENTS</code>. A resource loaded through a reference is only kept if every patient it references is the patient of the bundle.</li></ul><h3 id="limitation-other-patient-references-are-ignored" tabindex="-1">Limitation: other patient references are ignored <a class="header-anchor" href="#limitation-other-patient-references-are-ignored" aria-label="Permalink to &quot;Limitation: other patient references are ignored&quot;">​</a></h3><p>Only the element behind the chosen search parameter decides the patient. Other elements that may also reference a <code>Patient</code> are <strong>not</strong> used to assign the resource, to check consent or to detect several patients. For example, a child&#39;s <code>Coverage</code> with a parent as <code>subscriber</code> belongs to the child only.</p><p>This doesn&#39;t put another patient&#39;s data in the extraction. A reference in such an element is kept only if it is resolved as a linked group, and a referenced <code>Patient</code> other than the bundle&#39;s patient is rejected when it is loaded. Any reference that isn&#39;t resolved is replaced by a data-absent-reason during redaction, so the other patient&#39;s ID isn&#39;t exported either.</p><p>The following elements of the compartment definition may reference a <code>Patient</code> but are ignored. Elements that aren&#39;t part of the compartment definition, such as extensions, are never considered.</p><table tabindex="0"><thead><tr><th>Resource type</th><th>Element that decides the patient</th><th>Ignored elements that may reference a Patient</th></tr></thead><tbody><tr><td>AllergyIntolerance</td><td><code>patient</code></td><td><code>recorder</code>, <code>asserter</code></td></tr><tr><td>Basic</td><td><code>subject</code></td><td><code>author</code></td></tr><tr><td>CarePlan</td><td><code>subject</code></td><td><code>activity.detail.performer</code></td></tr><tr><td>CareTeam</td><td><code>subject</code></td><td><code>participant.member</code></td></tr><tr><td>Claim</td><td><code>patient</code></td><td><code>payee.party</code></td></tr><tr><td>Communication</td><td><code>subject</code></td><td><code>sender</code>, <code>recipient</code></td></tr><tr><td>CommunicationRequest</td><td><code>subject</code></td><td><code>sender</code>, <code>recipient</code>, <code>requester</code></td></tr><tr><td>Composition</td><td><code>subject</code></td><td><code>author</code>, <code>attester.party</code></td></tr><tr><td>Condition</td><td><code>subject</code></td><td><code>asserter</code></td></tr><tr><td>Coverage</td><td><code>beneficiary</code></td><td><code>policyHolder</code>, <code>subscriber</code>, <code>payor</code></td></tr><tr><td>DeviceRequest</td><td><code>subject</code></td><td><code>performer</code></td></tr><tr><td>DocumentManifest</td><td><code>subject</code></td><td><code>author</code>, <code>recipient</code></td></tr><tr><td>DocumentReference</td><td><code>subject</code></td><td><code>author</code></td></tr><tr><td>ExplanationOfBenefit</td><td><code>patient</code></td><td><code>payee.party</code></td></tr><tr><td>Invoice</td><td><code>subject</code></td><td><code>recipient</code></td></tr><tr><td>List</td><td><code>subject</code></td><td><code>source</code></td></tr><tr><td>MedicationAdministration</td><td><code>subject</code></td><td><code>performer.actor</code></td></tr><tr><td>MedicationDispense</td><td><code>subject</code></td><td><code>receiver</code></td></tr><tr><td>Observation</td><td><code>subject</code></td><td><code>performer</code></td></tr><tr><td>Procedure</td><td><code>subject</code></td><td><code>performer.actor</code></td></tr><tr><td>QuestionnaireResponse</td><td><code>subject</code></td><td><code>author</code></td></tr><tr><td>RequestGroup</td><td><code>subject</code></td><td><code>action.participant</code></td></tr><tr><td>ServiceRequest</td><td><code>subject</code></td><td><code>performer</code></td></tr></tbody></table><p>How to extract resources that belong to several patients is tracked in <a href="https://github.com/medizininformatik-initiative/torch/issues/1382" target="_blank" rel="noreferrer">#1382</a>.</p>',18))])}const P=c(h,[["render",u]]);export{C as __pageData,P as default};
